(6036153, 886541, 115307, '<td valign="top">I think the processing is a little overdone here. But what an interesting shot! The pineapples definitely surprised me. The one pineapple on top of the car really makes the shot.</td>', 'I think the processing is a little overdone here. But what an interesting shot! The pineapples definitely surprised me. The one pineapple on top of the car really makes the shot.', '2010-06-01 23:41:11.000000', NULL, 1),
(6036155, 886831, 105171, '<td valign="top">Great shot and what a clarity!</td>', 'Great shot and what a clarity!', '2010-06-01 23:42:55.000000', NULL, 1),
(6036156, 887064, 115307, '<td valign="top">Hahahahaha, Grandma makes this shot. Way more expressive with that shaken fist. I love it.<br/>I do think that you might have benefited from a closer crop.</td>', 'Hahahahaha, Grandma makes this shot. Way more expressive with that shaken fist. I love it.I do think that you might have benefited from a closer crop.', '2010-06-01 23:43:05.000000', NULL, 1),
(6036160, 887280, 105171, '<td valign="top">Nice. A tad more sharpness could help.</td>', 'Nice. A tad more sharpness could help.', '2010-06-01 23:45:31.000000', NULL, 1),
(6036162, 887270, 105171, '<td valign="top">Nice frame.  Excellent subject for HDR.</td>', 'Nice frame.  Excellent subject for HDR.', '2010-06-01 23:48:18.000000', NULL, 1),
(6036164, 886583, 115307, '<td valign="top">I think you could have cropped out some of the excessive blue sky on the top. Otherwise I really like the shot. I love the colors</td>', 'I think you could have cropped out some of the excessive blue sky on the top. Otherwise I really like the shot. I love the colors', '2010-06-01 23:50:35.000000', NULL, 1),
(6036168, 884372, 105171, '<td valign="top">Reflection of the pearl on the table adds value.</td>', 'Reflection of the pearl on the table adds value.', '2010-06-01 23:52:36.000000', NULL, 1),
(6036172, 886523, 105171, '<td valign="top">Nice effort. Missing a tad of sharpness on the subject - otherwise an interesting photo.</td>', 'Nice effort. Missing a tad of sharpness on the subject - otherwise an interesting photo.', '2010-06-01 23:54:09.000000', NULL, 1),
(6036233, 883976, 91783, '<td valign="top">i would have liked to see like a full body shot with this idea. good job though</td>', 'i would have liked to see like a full body shot with this idea. good job though', '2010-06-02 00:33:16.000000', NULL, 1),
(6036235, 886897, 91783, '<td valign="top">imo, simpler the border the better.</td>', 'imo, simpler the border the better.', '2010-06-02 00:34:47.000000', NULL, 1),
