(6036243, 883961, 110400, '<td valign="top">Very nicely done...without looking at the title I had a huge sense of Irish theme.  I looked at the title and noticed I was wrong, but I still love it. (9)</td>', 'Very nicely done...without looking at the title I had a huge sense of Irish theme.  I looked at the title and noticed I was wrong, but I still love it. (9)', '2010-06-02 00:40:43.000000', NULL, 1),
(6036248, 879690, 110400, '<td valign="top">I like the detail of the owl, but I do not like the green in the background at all.  It looks very unnatural.</td>', 'I like the detail of the owl, but I do not like the green in the background at all.  It looks very unnatural.', '2010-06-02 00:41:57.000000', NULL, 1),
(6036254, 887358, 110400, '<td valign="top">This would have been a good candidate for some HDR action if you had just been going after the barn and not the car.  I love barns like this and what can be done in photography to them.</td>', 'This would have been a good candidate for some HDR action if you had just been going after the barn and not the car.  I love barns like this and what can be done in photography to them.', '2010-06-02 00:43:27.000000', NULL, 1),
(6036261, 886860, 110400, '<td valign="top">I have looked at some of your other pictures with this model and think you are doing a great job.  She is very photogenic and the lighting really works. (8)</td>', 'I have looked at some of your other pictures with this model and think you are doing a great job.  She is very photogenic and the lighting really works. (8)', '2010-06-02 00:45:36.000000', NULL, 1),
(6036265, 885407, 110400, '<td valign="top">Wow...this almost looks photoshopped together.  You did an incredible job of getting everything lined up and the surfer adds the right additional element to move this from normal to superb. (8)</td>', 'Wow...this almost looks photoshopped together.  You did an incredible job of getting everything lined up and the surfer adds the right additional element to move this from normal to superb. (8)', '2010-06-02 00:47:32.000000', NULL, 1),
(6036267, 886195, 110400, '<td valign="top">Another great HDR candidate.</td>', 'Another great HDR candidate.', '2010-06-02 00:48:40.000000', NULL, 1),
(6036271, 886805, 110400, '<td valign="top">I like this one a lot.  Everything is so clear except the background.  I know that isn''t your fault, but I wish it was a little clearer between the trees and the hills because the fog seems to draw my eyes away from the rest of the scene. (6)</td>', 'I like this one a lot.  Everything is so clear except the background.  I know that isn''t your fault, but I wish it was a little clearer between the trees and the hills because the fog seems to draw my eyes away from the rest of the scene. (6)', '2010-06-02 00:50:46.000000', NULL, 1),
(6036274, 887005, 110400, '<td valign="top">Very sharp picture and I think that is what takes it from being more of a normal snapshot to being a good candidate in this challenge.</td>', 'Very sharp picture and I think that is what takes it from being more of a normal snapshot to being a good candidate in this challenge.', '2010-06-02 00:52:33.000000', NULL, 1),
(6036276, 879527, 110400, '<td valign="top">Very nice.  I might have tried to tone down the overly white reflection on the right side just to even out the whole effect.</td>', 'Very nice.  I might have tried to tone down the overly white reflection on the right side just to even out the whole effect.', '2010-06-02 00:54:44.000000', NULL, 1);
