(6038433, 887279, 77196, '<td valign="top">Love the feel of imposing fortress, dwarfing the human guard. Excellent symmetry, combined with rule of thirds. Also, the red jacket adds just a touch of color.</td>', 'Love the feel of imposing fortress, dwarfing the human guard. Excellent symmetry, combined with rule of thirds. Also, the red jacket adds just a touch of color.', '2010-06-02 23:19:27.000000', NULL, 1),
(6038435, 882294, 77196, '<td valign="top">IMO, a bit too much glare / hot spots. 6</td>', 'IMO, a bit too much glare / hot spots. 6', '2010-06-02 23:20:06.000000', NULL, 1),
(6038436, 886456, 77196, '<td valign="top">Nice intense eyes.</td>', 'Nice intense eyes.', '2010-06-02 23:20:29.000000', NULL, 1),
(6038439, 884040, 77196, '<td valign="top">Too high key - the shape of your main subject is lost in the wash out.</td>', 'Too high key - the shape of your main subject is lost in the wash out.', '2010-06-02 23:21:22.000000', NULL, 1),
