(6046191, 887386, 100393, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=859062" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/100000-104999/100393/120/Copyrighted_Image_Reuse_Prohibited_859062.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/100000-104999/100393/120/Copyrighted_Image_Reuse_Prohibited_859062.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/100000-104999/100393/120/Copyrighted_Image_Reuse_Prohibited_859062.jpg"/></a> <br/> <br/>Awarded jointly for May</td>', '  Awarded jointly for May', '2010-06-08 04:16:52.000000', NULL, 0),
