INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6047133, 887458, 63244, '<td valign="top">Thanks for NOT over saturating this place as the subtle colors and beautifully natural banding is what makes it so very unique! I miss it! :(  You''ve done it justice!!</td>', 'Thanks for NOT over saturating this place as the subtle colors and beautifully natural banding is what makes it so very unique! I miss it! :(  You''ve done it justice!!', '2010-06-08 21:20:29.000000', NULL, 0),
(6047135, 884638, 97225, '<td valign="top">I gave this a 9, and I''m surprised it didn''t finish higher. Not only is it  well composed, exposed and attractive, but just how often do you see a photo that captures such a defining moment?</td>', 'I gave this a 9, and I''m surprised it didn''t finish higher. Not only is it  well composed, exposed and attractive, but just how often do you see a photo that captures such a defining moment?', '2010-06-08 21:22:47.000000', NULL, 0),
(6047139, 887230, 21304, '<td valign="top">this is awesome!<br/>by the way, 4 ribbons out of 8 entries??!! holy sh*t! you''re coming in like a storm!</td>', 'this is awesome!by the way, 4 ribbons out of 8 entries??!! holy sh*t! you''re coming in like a storm!', '2010-06-08 21:25:36.000000', NULL, 0),
(6047175, 887181, 20130, '<td valign="top">not taking anything from the superb winning shot but i don''t think it is 111 places better than yours!</td>', 'not taking anything from the superb winning shot but i don''t think it is 111 places better than yours!', '2010-06-08 21:49:18.000000', NULL, 0),
(6047201, 885718, 61961, '<td valign="top">Nice work, Stan.  Plus I enjoyed reading your comments!  Congrats on the big blue ribbon.</td>', 'Nice work, Stan.  Plus I enjoyed reading your comments!  Congrats on the big blue ribbon.', '2010-06-08 22:03:00.000000', NULL, 0),
(6047312, 884629, 61961, '<td valign="top">Congratulations, Sarah.  Look at all those great comments -- everyone is so thrilled to see an abstract do well!</td>', 'Congratulations, Sarah.  Look at all those great comments -- everyone is so thrilled to see an abstract do well!', '2010-06-08 23:17:46.000000', NULL, 0),
(6047368, 885718, 50034, '<td valign="top">SWEET!  Great Capture!  <br/> <br/>Well, it is nice to know that someone wearing my name can get a BLUE, even if I can''t!<br/> <br/>Doubly SWEET!  :)</td>', 'SWEET!  Great Capture!   Well, it is nice to know that someone wearing my name can get a BLUE, even if I can''t! Doubly SWEET!  :)', '2010-06-08 23:44:43.000000', NULL, 0),
(6047423, 884638, 47852, '<td valign="top">Wow.. what a moment to capture.  I didn''t vote in this challenge, but going through the results I was a bit surprised to see this so far down.  I''m wondering if rotating this 180 degrees so that he was facing upwards would make a difference?  Something about facing downward gives this a feeling of coming to an end for me, when it''s clearly a moment of moving forward.  Either way, a great capture to be proud of.</td>', 'Wow.. what a moment to capture.  I didn''t vote in this challenge, but going through the results I was a bit surprised to see this so far down.  I''m wondering if rotating this 180 degrees so that he was facing upwards would make a difference?  Something about facing downward gives this a feeling of coming to an end for me, when it''s clearly a moment of moving forward.  Either way, a great capture to be proud of.', '2010-06-09 00:12:21.000000', NULL, 0),
(6047453, 883961, 105171, '<td valign="top">Congrats on top 10! Great variation of monochrome and nice portrait.</td>', 'Congrats on top 10! Great variation of monochrome and nice portrait.', '2010-06-09 00:31:55.000000', NULL, 0),
